fn copy(
    src: &Vec<i32>,
    s_start: usize,
    dest: &Vec<i32>,
    d_start: usize,
    len: usize,
) -> Vec<i32> {
    // Clone the destination to get a new vector of the same length
    let mut result = dest.clone();
    // Overwrite the specified segment in `result` with the slice from `src`
    let src_slice = &src[s_start..s_start + len];
    let dst_slice = &mut result[d_start..d_start + len];
    dst_slice.copy_from_slice(src_slice);
    result
}

